"""SE423 Listing Vault content: everything on the slides that could come as a listing question.

L(title, slide, items, note=memory aid, asked=real paper that asked for it, order=True when the order matters).
An item is 'Term | short explanation' or just 'Term'. `asked` only names a question in the real papers in exams/.
"""


def L(t, slide, items, note='', asked='', order=False, any_of=0):
    return dict(t=t, slide=slide, items=items, note=note, asked=asked, order=order, any_of=any_of)


